using System;
using System.Collections.Generic;
using Core;
using Core.Channels.General;
using Controllers.Rune;
using UI.Framework;
using UI.Framework.Base;
using UI.Framework.Manager;
using UnityEngine;
using UnityEngine.UI;

public class RunePanel : UIScreen
{
  [Header("Rune Panel Buttons")]
  [SerializeField] private Button equipButton;

  [Header("符文列表（动态生成）")]
  [SerializeField] private GameObject runeSlotPrefab;       // 符文插槽预制体
  [SerializeField] private GameObject runeSlotListPanel;    // 符文列表父级 Panel（生成的预制体挂在此 Panel 下）

  [Header("装备插槽")]
  [SerializeField] private RuneEquip runeEquip1;
  [SerializeField] private RuneEquip runeEquip2;

  [Header("拖拽")]
  [SerializeField] private Color dragTargetHighlightColor = new Color(1f, 0.92f, 0.46f, 1f); // 拖拽时装备插槽高亮色

  // 运行时动态生成的符文插槽列表
  private List<GameObject> runeSlotList = new List<GameObject>();

  // 选中状态
  private GameObject selectedRuneListItem;
  private RuneEquip selectedEquip; // 当前选中的装备插槽

  // ── 玩家拥有的符文（后续从存档加载） ──
  private List<int> ownedRuneIds = new List<int>();

  // 默认初始符文
  private static readonly List<int> DefaultRuneIds = new List<int> { 0, 0, 1, 1, 1 };

  /// <summary>玩家已拥有的符文 ID 列表</summary>
  public IReadOnlyList<int> OwnedRuneIds => ownedRuneIds;

  // --- 事件：通知 LobbyCanvas 更新图标视觉 ---
  /// <summary>符文装备事件 (slotIndex, equippedSprite)</summary>
  public event Action<int, Sprite> OnRuneEquipped;
  /// <summary>符文卸下事件 (slotIndex)</summary>
  public event Action<int> OnRuneUnequipped;
  /// <summary>符文列表项选中事件</summary>
  public event Action<RuneSlot> OnRuneItemSelected;

  // ──────────────────────────────────────────────
  //  UIScreen 生命周期
  // ──────────────────────────────────────────────

  protected override void Awake()
  {
    screenId = "RunePanel";
    base.Awake();
    UIManager.Instance.RegisterScreen(this);
    Initialize();
  }

  private void Initialize()
  {
    // 初始化已拥有符文（默认符文 + RuneInventory 中已购买的符文）
    ownedRuneIds = new List<int>(DefaultRuneIds);
    MergeInventoryRunes();

    // 绑定装备按钮
    if (equipButton != null)
      equipButton.onClick.AddListener(OnEquipClicked);

    // 动态生成符文列表（根据 ownedRuneIds 过滤 RuneDatabase）
    BuildRuneSlotList();

    // 默认装备：RuneEquip_1 ← RuneSlot[0], RuneEquip_2 ← RuneSlot[1]
    EquipDefaultRunes();

    // 刷新已装备标记 + 已装备符文排到最前面
    RefreshAllEquippedMarks();
    ReorderEquippedToFront();

    // 订阅装备插槽选中事件，默认选中插槽1
    if (runeEquip1 != null)
    {
      runeEquip1.OnSelected += OnEquipSlotSelected;
      runeEquip1.OnDropReceived += OnRuneDropReceived;      // 拖拽丢落
      selectedEquip = runeEquip1;
      runeEquip1.SetSelected(true);
    }
    if (runeEquip2 != null)
    {
      runeEquip2.OnSelected += OnEquipSlotSelected;
      runeEquip2.OnDropReceived += OnRuneDropReceived;      // 拖拽丢落
    }

    // 订阅符文拖拽事件（全局，用于高亮可拖放区域）
    RuneSlot.OnDragStarted += OnAnyRuneDragStarted;
    RuneSlot.OnDragEnded += OnAnyRuneDragEnded;
  }

  protected override void OnBeforeOpen()
  {
    base.OnBeforeOpen();

    // 检查是否有新购买的符文，如有则重建列表
    if (MergeInventoryRunes())
    {
      BuildRuneSlotList();
      RestoreEquipReferences();
    }

    // 刷新已装备标记 + 已装备符文排到最前面
    RefreshAllEquippedMarks();
    ReorderEquippedToFront();

    // 取消旧的选中，重新选中列表第 1 项
    DeselectAllItems();
    if (runeSlotList.Count > 0)
      SetRuneSlotItemSelected(runeSlotList[0]);

    // 默认选中装备槽 1
    if (selectedEquip != runeEquip1)
    {
      selectedEquip?.SetSelected(false);
      selectedEquip = runeEquip1;
    }
    if (runeEquip1 != null)
      runeEquip1.SetSelected(true);
  }

  protected override void OnAfterClose()
  {
    base.OnAfterClose();
    DeselectAllItems();
  }

  // ──────────────────────────────────────────────
  //  RuneInventory 同步
  // ──────────────────────────────────────────────

  /// <summary>
  /// 从默认符文 + RuneInventory 已购买符文重建 ownedRuneIds。
  /// 返回 true 表示列表有变化（有新购买的符文）。
  /// </summary>
  private bool MergeInventoryRunes()
  {
    var newIds = new List<int>(DefaultRuneIds);
    newIds.AddRange(RuneInventory.GetAllRuneIds());

    if (newIds.Count == ownedRuneIds.Count) return false;

    ownedRuneIds = newIds;
    Debug.Log($"[RunePanel] 符文列表更新：共 {ownedRuneIds.Count} 个（默认 {DefaultRuneIds.Count} + 购买 {newIds.Count - DefaultRuneIds.Count}）");
    return true;
  }

  /// <summary>
  /// 重建列表后，重新关联 RuneEquip 的 RuneSlot 引用
  /// （旧引用已随列表销毁，需要指向新的 RuneSlot 实例）
  /// </summary>
  private void RestoreEquipReferences()
  {
    foreach (var go in runeSlotList)
    {
      if (go == null) continue;
      var slot = go.GetComponent<RuneSlot>();
      if (slot == null || slot.RuneData == null) continue;

      int runeId = slot.RuneData.runeId;

      if (runeEquip1 != null && runeEquip1.EquippedRuneId == runeId && runeEquip1.EquippedRuneSlot == null)
      {
        runeEquip1.Equip(runeId, slot.RuneData.icon, slot);
      }
      else if (runeEquip2 != null && runeEquip2.EquippedRuneId == runeId && runeEquip2.EquippedRuneSlot == null)
      {
        runeEquip2.Equip(runeId, slot.RuneData.icon, slot);
      }
    }
  }

  // ──────────────────────────────────────────────
  //  动态生成符文插槽
  // ──────────────────────────────────────────────

  private void BuildRuneSlotList()
  {
    // 清空上一次生成的列表
    foreach (var go in runeSlotList)
      Destroy(go);
    runeSlotList.Clear();

    if (runeSlotPrefab == null)
    {
      Debug.LogError("[RunePanel] runeSlotPrefab 未赋值，无法动态生成符文列表");
      return;
    }

    if (runeSlotListPanel == null)
    {
      Debug.LogError("[RunePanel] runeSlotListPanel 未赋值，无法动态生成符文列表");
      return;
    }

    // 从 Resources 加载符文数据库，构建 runeId → RuneDataSO 的快速查找
    var database = Resources.Load<RuneDatabaseSO>("RuneData/RuneDatabase");
    if (database == null || database.allRunes.Count == 0)
    {
      Debug.LogWarning("[RunePanel] 未找到 RuneDatabase 或数据为空");
      return;
    }

    // 构建 runeId → RuneDataSO 字典
    var runeDataMap = new Dictionary<int, RuneDataSO>();
    foreach (var data in database.allRunes)
      if (data != null && !runeDataMap.ContainsKey(data.runeId))
        runeDataMap[data.runeId] = data;

    // 对 ownedRuneIds 排序（自动按 runeId 升序排列）
    ownedRuneIds.Sort();

    // 每个 ID 生成一个插槽（支持重复符文）
    for (int i = 0; i < ownedRuneIds.Count; i++)
    {
      int runeId = ownedRuneIds[i];

      if (!runeDataMap.TryGetValue(runeId, out var runeData))
      {
        Debug.LogWarning($"[RunePanel] ownedRuneIds 包含未在数据库中注册的 ID: {runeId}");
        continue;
      }

      // 实例化预制体
      var go = Instantiate(runeSlotPrefab, runeSlotListPanel.transform);
      go.name = $"RuneSlot_{runeId}_{runeData.runeName}_{i:D2}";

      // 设置符文数据
      var runeSlot = go.GetComponent<RuneSlot>();
      if (runeSlot != null)
      {
        runeSlot.Setup(runeData);
        runeSlot.OnClicked += OnRuneSlotClicked;

        // 标记已装备状态
        bool isEquipped = (runeEquip1 != null && runeEquip1.EquippedRuneId == runeId) ||
                          (runeEquip2 != null && runeEquip2.EquippedRuneId == runeId);
        runeSlot.SetEquipped(isEquipped);
      }

      runeSlotList.Add(go);
    }
  }

  private void OnRuneSlotClicked(RuneSlot runeSlot)
  {
    if (runeSlot == null || runeSlot.gameObject == selectedRuneListItem)
      return;

    SetRuneSlotItemSelected(runeSlot.gameObject);
  }

  /// <summary>
  /// 默认装备：取前两个不同种类的符文分别装备到两个插槽
  /// </summary>
  private void EquipDefaultRunes()
  {
    var usedRuneIds = new HashSet<int>();
    int equipIndex = 0;
    RuneEquip[] equipSlots = { runeEquip1, runeEquip2 };

    for (int i = 0; i < runeSlotList.Count && equipIndex < 2; i++)
    {
      var slot = runeSlotList[i].GetComponent<RuneSlot>();
      if (slot == null || slot.RuneData == null)
        continue;

      int runeId = slot.RuneData.runeId;

      // 跳过已装备过的符文种类
      if (usedRuneIds.Contains(runeId))
        continue;

      usedRuneIds.Add(runeId);
      var equip = equipSlots[equipIndex];
      if (equip != null)
      {
        equip.Equip(runeId, slot.RuneData.icon, slot);
        equipIndex++;
      }
    }

    if (equipIndex == 0)
      Debug.LogWarning("[RunePanel] 没有可装备的默认符文");
  }

  private void SetRuneSlotItemSelected(GameObject item)
  {
    // 取消选中之前的项
    if (selectedRuneListItem != null && selectedRuneListItem != item)
    {
      var prevSlot = selectedRuneListItem.GetComponent<RuneSlot>();
      prevSlot?.PlayDeselect();
    }

    selectedRuneListItem = item;

    // 选中新项 + 显示详情
    var runeSlot = item?.GetComponent<RuneSlot>();
    if (runeSlot != null)
    {
      runeSlot.PlaySelect();

      var args = new RuneEquipArgs(
          runeSlot.SlotId,
          runeSlot.RuneName,
          runeSlot.RunePowers,
          runeSlot.SpecialPowerName,
          runeSlot.SpecialPowerDescription
      );
      EventChannelLocator.MainContainer.runeInfoChannel.Raise(args);

      OnRuneItemSelected?.Invoke(runeSlot);
    }
  }

  // ──────────────────────────────────────────────
  //  装备插槽选择
  // ──────────────────────────────────────────────

  private void OnEquipSlotSelected(RuneEquip equip)
  {
    if (equip == null || equip == selectedEquip)
      return;

    // 取消选中旧插槽
    selectedEquip?.SetSelected(false);

    // 选中新插槽
    selectedEquip = equip;
    selectedEquip.SetSelected(true);
  }

  // ──────────────────────────────────────────────
  //  装备符文
  // ──────────────────────────────────────────────

  private void OnEquipClicked()
  {
    if (selectedRuneListItem == null)
    {
      Debug.LogWarning("[RunePanel] 没有选中的符文图标");
      return;
    }

    var runeSlot = selectedRuneListItem.GetComponent<RuneSlot>();
    if (runeSlot == null)
    {
      Debug.LogWarning("[RunePanel] 选中的符文图标没有 RuneSlot 组件");
      return;
    }

    if (selectedEquip == null)
    {
      Debug.LogWarning("[RunePanel] 没有选中的装备插槽");
      return;
    }

    if (EquipRune(runeSlot, selectedEquip))
    {
      // 装备成功 → 刷新标记并重排
      RefreshAllEquippedMarks();
      ReorderEquippedToFront();
    }
  }

  /// <summary>
  /// 执行装备 / 调换逻辑，供点击装备按钮和拖拽丢落共用
  /// </summary>
  /// <returns>true = 装备成功 / 调换成功</returns>
  public bool EquipRune(RuneSlot runeSlot, RuneEquip equipSlot)
  {
    if (runeSlot == null || equipSlot == null)
    {
      Debug.LogWarning("[RunePanel] EquipRune 参数为空");
      return false;
    }

    if (runeSlot.RuneData == null)
    {
      Debug.LogWarning("[RunePanel] 符文数据为空，无法装备");
      return false;
    }

    int newRuneId = runeSlot.RuneData.runeId;

    // 情况1：该符文已装备在当前插槽 → 无效果
    if (equipSlot.EquippedRuneId == newRuneId)
    {
      Debug.Log("[RunePanel] 该符文已装备在选中插槽，无变化");
      return false;
    }

    if (runeSlot.RuneData.icon == null)
    {
      Debug.LogWarning("[RunePanel] 符文没有图标数据");
      return false;
    }

    Sprite newIcon = runeSlot.RuneData.icon;
    RuneEquip otherEquip = (equipSlot == runeEquip1) ? runeEquip2 : runeEquip1;

    // 情况2：该符文已装备在另一个插槽 → 调换两插槽的符文
    if (otherEquip != null && otherEquip.EquippedRuneId == newRuneId)
    {
      int swappedRuneId = equipSlot.EquippedRuneId;
      Sprite swappedIcon = equipSlot.EquippedIcon;
      RuneSlot swappedSlot = equipSlot.EquippedRuneSlot;

      // 选中插槽 ← 新符文
      equipSlot.Equip(newRuneId, newIcon, runeSlot);

      if (swappedRuneId != -1)
      {
        // 另一插槽 ← 旧符文（调换）
        otherEquip.Equip(swappedRuneId, swappedIcon, swappedSlot);
        OnRuneEquipped?.Invoke(otherEquip.EquipIndex, swappedIcon);
      }
      else
      {
        // 另一插槽被腾空（移动而非调换）
        otherEquip.Unequip();
        OnRuneUnequipped?.Invoke(otherEquip.EquipIndex);
      }

      // 通知 LobbyCanvas 更新选中插槽图标
      OnRuneEquipped?.Invoke(equipSlot.EquipIndex, newIcon);

      Debug.Log($"[RunePanel] 调换符文: 插槽{equipSlot.EquipIndex}←{newRuneId}, 插槽{otherEquip.EquipIndex}←{swappedRuneId}");
    }
    else
    {
      // 情况3：全新装备 → 直接装备到选中插槽
      equipSlot.Equip(newRuneId, newIcon, runeSlot);
      ApplyEquipEffect(newRuneId);

      // 通知 LobbyCanvas
      OnRuneEquipped?.Invoke(equipSlot.EquipIndex, newIcon);

      Debug.Log($"[RunePanel] 装备符文: 插槽{equipSlot.EquipIndex} ← {runeSlot.RuneName}");
    }

    return true;
  }

  /// <summary>应用装备效果（留空，仅记录装备符文，进入游戏时调用）</summary>
  private void ApplyEquipEffect(int runeId)
  {
    // TODO: 实际游戏效果在进入游戏时根据 EquippedRuneId 应用
  }

  // ──────────────────────────────────────────────
  //  已装备标记刷新
  // ──────────────────────────────────────────────

  /// <summary>遍历所有 RuneSlot，刷新已装备标记（按实例精确匹配）</summary>
  private void RefreshAllEquippedMarks()
  {
    foreach (var go in runeSlotList)
    {
      var runeSlot = go.GetComponent<RuneSlot>();
      if (runeSlot == null) continue;

      bool isEquipped = (runeEquip1 != null && runeEquip1.EquippedRuneSlot == runeSlot) ||
                        (runeEquip2 != null && runeEquip2.EquippedRuneSlot == runeSlot);
      runeSlot.SetEquipped(isEquipped);
    }
  }

  /// <summary>将已装备的符文插槽移到列表最前面</summary>
  private void ReorderEquippedToFront()
  {
    // 收集已装备的 GameObject
    var equippedGOs = new List<GameObject>();
    var unequippedGOs = new List<GameObject>();
    foreach (var go in runeSlotList)
    {
      if (go == null) continue;
      var runeSlot = go.GetComponent<RuneSlot>();
      if (runeSlot == null) continue;

      bool isEquipped = (runeEquip1 != null && runeEquip1.EquippedRuneSlot == runeSlot) ||
                        (runeEquip2 != null && runeEquip2.EquippedRuneSlot == runeSlot);
      if (isEquipped)
        equippedGOs.Add(go);
      else
        unequippedGOs.Add(go);
    }

    // 按顺序设置 hierarchy 层级
    runeSlotList.Clear();
    int siblingIndex = 0;
    foreach (var go in equippedGOs)
    {
      go.transform.SetSiblingIndex(siblingIndex++);
      runeSlotList.Add(go);
    }
    foreach (var go in unequippedGOs)
    {
      go.transform.SetSiblingIndex(siblingIndex++);
      runeSlotList.Add(go);
    }
  }

  // ──────────────────────────────────────────────
  //  外部接口
  // ──────────────────────────────────────────────

  /// <summary>获取当前选中的装备插槽</summary>
  public RuneEquip GetSelectedEquip() => selectedEquip;
  public RuneEquip GetEquip1() => runeEquip1;
  public RuneEquip GetEquip2() => runeEquip2;

  /// <summary>由 LobbyCanvas 调用，选中指定索引的装备插槽 (0/1)</summary>
  public void SelectEquipSlot(int index)
  {
    var target = index == 0 ? runeEquip1 : runeEquip2;
    if (target != null)
      OnEquipSlotSelected(target);
  }

  // ──────────────────────────────────────────────
  //  取消所有选中
  // ──────────────────────────────────────────────

  private void DeselectAllItems()
  {
    selectedRuneListItem = null;
    selectedEquip?.SetSelected(false);
    selectedEquip = null;
  }

  // ──────────────────────────────────────────────
  //  拖拽丢落处理
  // ──────────────────────────────────────────────

  private void OnDestroy()
  {
    // 取消订阅事件，防止内存泄漏
    RuneSlot.OnDragStarted -= OnAnyRuneDragStarted;
    RuneSlot.OnDragEnded -= OnAnyRuneDragEnded;

    if (runeEquip1 != null)
    {
      runeEquip1.OnSelected -= OnEquipSlotSelected;
      runeEquip1.OnDropReceived -= OnRuneDropReceived;
    }
    if (runeEquip2 != null)
    {
      runeEquip2.OnSelected -= OnEquipSlotSelected;
      runeEquip2.OnDropReceived -= OnRuneDropReceived;
    }
  }

  /// <summary>拖拽开始时高亮装备插槽，提示可拖放区域</summary>
  private void OnAnyRuneDragStarted(RuneSlot runeSlot)
  {
    SetEquipSlotsHighlight(true);
  }

  /// <summary>拖拽结束时取消装备插槽高亮</summary>
  private void OnAnyRuneDragEnded(RuneSlot runeSlot)
  {
    SetEquipSlotsHighlight(false);
  }

  /// <summary>符文拖拽丢落到装备插槽上时执行装备</summary>
  private void OnRuneDropReceived(RuneEquip equip, RuneSlot runeSlot)
  {
    if (EquipRune(runeSlot, equip))
    {
      // 装备成功 → 刷新标记并重排
      RefreshAllEquippedMarks();
      ReorderEquippedToFront();

      // 选中该装备插槽（同步 UI 选中状态）
      OnEquipSlotSelected(equip);
    }
  }

  /// <summary>切换装备插槽的高亮状态</summary>
  private void SetEquipSlotsHighlight(bool highlight)
  {
    if (runeEquip1 != null)
      runeEquip1.SetHighlight(highlight, dragTargetHighlightColor);
    if (runeEquip2 != null)
      runeEquip2.SetHighlight(highlight, dragTargetHighlightColor);
  }
}

using System.Collections;
using System.Collections.Generic;
using Core;
using UnityEngine;
using UnityEngine.UI;

namespace UI
{
  public class RuneInfoPanel : MonoBehaviour
  {
    private Text runeNameText;
    private Text runePowers_1Text;
    private Text runePowers_2Text;
    private Text specialPowerNameText;
    private Text specialPowerDescriptionText;

    void Awake()
    {
      Intilize();
    }

    private void Intilize()
    {
      // 使用安全的组件获取方式
      runeNameText = SafeGetComponent<Text>(transform.Find("RuneName"));
      specialPowerNameText = SafeGetComponent<Text>(
          transform.Find("SpecialPower/SpecialName")
      );
      specialPowerDescriptionText = SafeGetComponent<Text>(
          transform.Find("SpecialPower/SpecialDescription")
      );
      runePowers_1Text = SafeGetComponent<Text>(transform.Find("PowerPanel/PowerInfo_1"));
      runePowers_2Text = SafeGetComponent<Text>(transform.Find("PowerPanel/PowerInfo_2"));
    }

    private T SafeGetComponent<T>(Transform parent)
        where T : Component
    {
      if (parent == null)
      {
        Debug.LogWarning($"[RuneInfoPanel] 找不到父对象");
        return null;
      }

      T component = parent.GetComponent<T>();
      if (component == null)
      {
        Debug.LogWarning($"[RuneInfoPanel] 找不到 {typeof(T).Name} 组件");
      }
      return component;
    }

    private void OnEnable()
    {
      if (EventChannelLocator.MainContainer != null)
        EventChannelLocator.MainContainer.runeInfoChannel.RegisterListener(RuneEventTran);
    }

    private void OnDisable()
    {
      UnregisterEvents();
    }

    private void OnDestroy()
    {
      UnregisterEvents();
    }

    private void UnregisterEvents()
    {
      if (EventChannelLocator.MainContainer != null)
        EventChannelLocator.MainContainer.runeInfoChannel.UnregisterListener(RuneEventTran);
    }

    private void RuneEventTran(RuneEquipArgs runeEquipArgs)
    {
      // 防御性检查：对象可能已销毁
      if (this == null || runeEquipArgs == null)
        return;

      UpdateRuneInfo(
          runeEquipArgs.runeName,
          runeEquipArgs.runePowers,
          runeEquipArgs.specialPowerName,
          runeEquipArgs.specialPowerDescription
      );
    }

    private void UpdateRuneInfo(
        string runeName,
        Dictionary<int, string> runePowers,
        string specialPowerName,
        string specialPowerDescription
    )
    {
      Debug.Log("UpdateRuneInfo");

      // 逐一检查每个Text组件是否有效
      if (runeNameText != null)
        runeNameText.text = runeName;

      if (specialPowerNameText != null)
        specialPowerNameText.text = specialPowerName;

      if (specialPowerDescriptionText != null)
        specialPowerDescriptionText.text = specialPowerDescription;

      if (runePowers == null)
        return;

      int index = 1;
      foreach (var power in runePowers)
      {
        string text =
            power.Key > 0 ? $"+{power.Key}{power.Value}" : $"-{power.Key}{power.Value}";

        if (index == 1 && runePowers_1Text != null)
        {
          runePowers_1Text.text = text;
        }
        else if (index == 2 && runePowers_2Text != null)
        {
          runePowers_2Text.text = text;
        }
        index++;
      }
    }
  }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UI.Framework.Base;

namespace UI.Framework
{
    public class RuneSlot : UIWidget, IPointerClickHandler, IPointerEnterHandler, IPointerExitHandler,
                             IBeginDragHandler, IDragHandler, IEndDragHandler
    {
        [Header("RuneSlot UI")]
        [SerializeField] private Image iconImage;
        [SerializeField] private Text nameText;

        [Header("RuneSlot Data")]
        [SerializeField] private int slotId;

        [Header("选中高亮")]
        [SerializeField] private Image bgcImage; // BGC 子对象的 Image（拖拽赋值）
        [SerializeField] private Sprite selectedSprite;   // 选中时的 BGC 图片
        [SerializeField] private Sprite deselectedSprite; // 未选中时的 BGC 图片
        [SerializeField] private Sprite hoverSprite;      // 悬浮时的 BGC 图片

        [Header("已装备标记")]
        [SerializeField] private GameObject equippedMarkObject; // 已装备标记（含子对象 TextMeshProUGUI，拖拽赋值）

        [Header("拖拽")]
        [SerializeField][Range(0f, 1f)] private float dragGhostAlpha = 0.6f; // 拖拽虚影透明度

        /// <summary>点击事件，供 RunePanel 订阅</summary>
        public event Action<RuneSlot> OnClicked;

        /// <summary>开始拖拽符文时触发，供 RunePanel 订阅</summary>
        public static event Action<RuneSlot> OnDragStarted;

        /// <summary>拖拽结束时触发（无论是否落在有效区域），供 RunePanel 订阅</summary>
        public static event Action<RuneSlot> OnDragEnded;

        // 通过 Setup() 注入的符文数据资产
        private RuneDataSO runeData;

        // 拖拽状态
        private Image dragGhostImage;
        private RectTransform dragGhostRect;
        private Canvas dragCanvas;

        // ── 只读公开属性 ──

        public int SlotId => slotId;
        public RuneDataSO RuneData => runeData;

        /// <summary>向后兼容：从 runeData.powers 构建字典</summary>
        public Dictionary<int, string> RunePowers
        {
            get
            {
                var dict = new Dictionary<int, string>();
                if (runeData != null)
                    foreach (var p in runeData.powers)
                        dict[p.value] = p.label;
                return dict;
            }
        }

        public string RuneName => runeData != null ? runeData.runeName : string.Empty;
        public string SpecialPowerName => runeData != null ? runeData.specialPowerName : string.Empty;
        public string SpecialPowerDescription => runeData != null ? runeData.specialPowerDescription : string.Empty;

        // ── 外部注入 ──

        /// <summary>用 RuneDataSO 设置该槽位的符文数据</summary>
        public void Setup(RuneDataSO data)
        {
            runeData = data;

            if (data == null)
            {
                if (iconImage != null) iconImage.sprite = null;
                if (nameText != null) nameText.text = string.Empty;
                return;
            }

            slotId = data.runeId;

            if (iconImage != null)
                iconImage.sprite = data.icon;

            if (nameText != null)
                nameText.text = data.runeName;
        }

        /// <summary>设置已装备标记的显示状态</summary>
        public void SetEquipped(bool equipped)
        {
            if (equippedMarkObject != null)
                equippedMarkObject.SetActive(equipped);
        }

        // ── UIWidget 生命周期 ──

        protected override void AutoBindComponents()
        {
            // 自动查找 Icon 子对象
            if (iconImage == null)
            {
                var iconTr = transform.Find("Icon");
                if (iconTr != null)
                    iconImage = iconTr.GetComponent<Image>();
            }

            // 自动查找 Name 子对象
            if (nameText == null)
            {
                var nameTr = transform.Find("Name");
                if (nameTr != null)
                    nameText = nameTr.GetComponent<Text>();
            }

            // 确保自身 Image 可接收射线，避免 prefab 根节点没有 Image 时无法触发点击
            var image = GetComponent<Image>();
            if (image == null)
            {
                image = gameObject.AddComponent<Image>();
                image.color = Color.clear;
            }
            image.raycastTarget = true;

            // 初始状态设为未选中图片
            if (bgcImage != null && deselectedSprite != null)
                bgcImage.sprite = deselectedSprite;

            // 已装备标记初始为不激活（由 SetEquipped 控制）
            if (equippedMarkObject != null)
                equippedMarkObject.SetActive(false);
        }

        // ──────────────────────────────────────────────
        //  选中 / 取消选中 → 切换 BGC 图片
        // ──────────────────────────────────────────────

        protected override void OnSelectCompleted()
        {
            if (bgcImage != null && selectedSprite != null)
                bgcImage.sprite = selectedSprite;
        }

        protected override void OnDeselectCompleted()
        {
            if (bgcImage != null && deselectedSprite != null)
                bgcImage.sprite = deselectedSprite;
        }

        // ── 指针事件（点击 + 悬浮） ──

        public void OnPointerClick(PointerEventData eventData)
        {
            OnClicked?.Invoke(this);
        }

        public void OnPointerEnter(PointerEventData eventData)
        {
            PlayHoverEnter();

            // 未选中时切换为悬浮图片
            if (!IsSelected && bgcImage != null && hoverSprite != null)
                bgcImage.sprite = hoverSprite;
        }

        public void OnPointerExit(PointerEventData eventData)
        {
            PlayHoverExit();

            // 恢复为对应状态的图片
            if (bgcImage == null) return;
            bgcImage.sprite = IsSelected ? selectedSprite : deselectedSprite;
        }

        // ── 拖拽（IBeginDragHandler / IDragHandler / IEndDragHandler） ──

        public void OnBeginDrag(PointerEventData eventData)
        {
            // 没有数据的符文不允许拖拽
            if (runeData == null || iconImage == null || iconImage.sprite == null)
                return;

            // 查找根 Canvas
            if (dragCanvas == null)
                dragCanvas = GetComponentInParent<Canvas>();
            if (dragCanvas == null) return;

            // 创建虚影 GameObject
            var ghostGO = new GameObject($"{name}_DragGhost", typeof(Image));
            ghostGO.transform.SetParent(dragCanvas.transform, false);
            ghostGO.transform.SetAsLastSibling();

            dragGhostImage = ghostGO.GetComponent<Image>();
            dragGhostImage.sprite = iconImage.sprite;
            dragGhostImage.raycastTarget = false;
            dragGhostImage.color = new Color(1f, 1f, 1f, dragGhostAlpha);

            dragGhostRect = ghostGO.GetComponent<RectTransform>();
            // 保持与原始图标一致的尺寸和比例
            dragGhostRect.sizeDelta = iconImage.rectTransform.sizeDelta;
            dragGhostRect.pivot = iconImage.rectTransform.pivot;

            // 初始位置对齐鼠标
            UpdateGhostPosition(eventData);

            // 通知 RunePanel 拖拽开始
            OnDragStarted?.Invoke(this);
        }

        public void OnDrag(PointerEventData eventData)
        {
            if (dragGhostRect == null || dragCanvas == null) return;
            UpdateGhostPosition(eventData);
        }

        public void OnEndDrag(PointerEventData eventData)
        {
            // 销毁虚影
            if (dragGhostImage != null)
            {
                Destroy(dragGhostImage.gameObject);
                dragGhostImage = null;
                dragGhostRect = null;
            }

            // 通知拖拽结束
            OnDragEnded?.Invoke(this);
        }

        /// <summary>将虚影移动到当前鼠标位置</summary>
        private void UpdateGhostPosition(PointerEventData eventData)
        {
            if (dragGhostRect == null || dragCanvas == null) return;

            RectTransformUtility.ScreenPointToLocalPointInRectangle(
                dragCanvas.transform as RectTransform,
                eventData.position,
                eventData.pressEventCamera,
                out var localPos
            );
            dragGhostRect.localPosition = localPos;
        }
    }
}

