    public event Action<RuneEquip, RuneSlot> OnDropReceived;

    // ──────────────────────────────────────────────
    //  装备 / 卸下
    // ──────────────────────────────────────────────

    /// <summary>装备符文到该插槽</summary>
    public void Equip(int runeId, Sprite icon, RuneSlot runeSlot)
    {
        EquippedRuneId = runeId;
        EquippedIcon = icon;
        EquippedRuneSlot = runeSlot;

        if (iconImage != null)
            iconImage.sprite = icon;
    }

    /// <summary>卸下当前符文</summary>
    public void Unequip()
    {
        EquippedRuneId = -1;
        EquippedIcon = null;
        EquippedRuneSlot = null;

        if (iconImage != null)
            iconImage.sprite = null;
    }

    // ──────────────────────────────────────────────
    //  选中 / 取消选中
    // ──────────────────────────────────────────────

