        if (iconImage == null)
        {
            var iconTr = transform.Find("Icon");
            if (iconTr != null)
                iconImage = iconTr.GetComponent<Image>();
        }

        // 确保自身 Image 可接收射线
        var img = GetComponent<Image>();
        if (img != null)
            img.raycastTarget = true;
    }

    // ──────────────────────────────────────────────
    //  点击 → 选中该插槽
    // ──────────────────────────────────────────────

    public void OnPointerClick(PointerEventData eventData)
    {
        OnSelected?.Invoke(this);
    }

    public void OnPointerEnter(PointerEventData eventData)
    {
        PlayHoverEnter();
    }

    public void OnPointerExit(PointerEventData eventData)
    {
        PlayHoverExit();
    }

    // ──────────────────────────────────────────────
    //  拖拽丢落（IDropHandler）
    // ──────────────────────────────────────────────

    public void OnDrop(PointerEventData eventData)
    {
        if (eventData.pointerDrag == null) return;

        var runeSlot = eventData.pointerDrag.GetComponent<RuneSlot>();
        if (runeSlot != null && runeSlot.RuneData != null)
            OnDropReceived?.Invoke(this, runeSlot);
    }

    /// <summary>
    /// 设置拖拽目标高亮状态（由 RunePanel 在拖拽开始/结束时调用）
    /// </summary>
    public void SetHighlight(bool highlight, Color highlightColor)
    {
        if (highlightImage == null) return;
        highlightImage.color = highlight ? highlightColor : normalColor;
    }
}

