using System.Collections;
using Controllers.Item;
using UnityEngine;

namespace Controllers.Rune
{
    /// <summary>
    /// 符文掉落物 — 从敌人身上掉落，以抛物线轨迹飞出去然后落地
    /// 玩家靠近拾取后，符文效果即时应用到玩家属性
    /// </summary>
    public class DropItemRune : DropItemBase
    {
        [Header("符文数据")]
        [SerializeField] private RuneDataSO runeData;

        [Header("抛物线参数")]
        [SerializeField] private float launchAngleMin = 50f;       // 最小发射仰角（度）
        [SerializeField] private float launchAngleMax = 70f;       // 最大发射仰角（度）
        [SerializeField] private float launchSpeed = 6f;           // 发射初速度
        [SerializeField] private float launchRandomRadius = 3f;    // 落点随机散布半径
        [SerializeField] private float spinTorque = 3f;            // 飞行中的自旋扭矩

        [Header("落地检测")]
        [SerializeField] private float landVelocityThreshold = 0.2f; // 判定落地的速度阈值
        [SerializeField] private float groundCheckDistance = 2f;     // 向下检测地面的距离
        [SerializeField] private LayerMask groundLayer = -1;         // 地面层（-1 = Everything）
        [SerializeField] private float groundYOffset = 0.05f;        // 落地后离地高度

        [Header("生命周期")]
        [SerializeField] private float maxLifetime = 30f;           // 无人拾取时自动消失的时间


        [Header("子类特效")]
        [SerializeField] private GameObject trail;
        [SerializeField] private GameObject realyFx;
        // ── 运行时状态 ──
        private bool hasLanded = false;
        private float launchTime;               // 发射时刻（防 OnCollisionEnter 误触）
        private Coroutine landCheckCoroutine;
        private Coroutine lifetimeCoroutine;

        // ======================================================================
        //  Setup — 由敌人掉落时调用，传入掉落的符文数据
        // ======================================================================

        /// <summary>设置该掉落物对应的符文数据</summary>
        public void Setup(RuneDataSO data)
        {
            runeData = data;
        }

        /// <summary>获取该掉落物携带的符文数据</summary>
        public RuneDataSO GetRuneData() => runeData;

        // ======================================================================
        //  生命周期（继承自 DropItemBase）
        // ======================================================================

        /// <summary>
        /// GameObject 被激活时调用：
        /// 基类 OnEnable() 会重置飞行状态并调用 ApplyExplosionEffect()
        /// 我们 override ApplyExplosionEffect() 来实现抛物线
        /// </summary>
        protected override void OnEnable()
        {
            hasLanded = false;

            // 清除之前的协程
            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }

            base.OnEnable();
        }

        protected override void OnDisable()
        {
            base.OnDisable();

            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }
        }

        // ======================================================================
        //  抛物线弹射（override 基类的简单爆炸）
        // ======================================================================

        /// <summary>
        /// 重写基类的 ApplyExplosionEffect：
        /// 以高抛角度将符文弹射出去，形成抛物线轨迹
        /// </summary>
        protected override void ApplyExplosionEffect()
        {
            if (Rb == null)
                return;

            // 1. 重置物理状态
            Rb.velocity = Vector3.zero;
            Rb.angularVelocity = Vector3.zero;
            Rb.isKinematic = false;
            Rb.useGravity = true;

            // 记录发射时刻，防止 OnCollisionEnter 误触
            launchTime = UnityEngine.Time.time;

            // 2. 随机偏移落点方向（在敌人周围散布）
            Vector2 randomCircle = Random.insideUnitCircle.normalized;
            Vector3 horizontalDir = new Vector3(randomCircle.x, 0, randomCircle.y);

            // 3. 计算发射速度
            //    已知水平距离 distance，仰角 angle，初速度 launchSpeed
            //    水平分量: v_x = launchSpeed * cos(angle)
            //    垂直分量: v_y = launchSpeed * sin(angle)
            float angle = Random.Range(launchAngleMin, launchAngleMax);
            float angleRad = angle * Mathf.Deg2Rad;

            Vector3 launchVelocity = horizontalDir * launchSpeed * Mathf.Cos(angleRad)
                                   + Vector3.up * launchSpeed * Mathf.Sin(angleRad);

            // 4. 施加瞬时速度
            Rb.AddForce(launchVelocity, ForceMode.VelocityChange);

            // 5. 添加旋转（让符文在空中翻转）
            Rb.AddTorque(new Vector3(
                Random.Range(-1f, 1f),
                Random.Range(-1f, 1f),
                Random.Range(-1f, 1f)
            ) * spinTorque, ForceMode.VelocityChange);

            // 5.5 增加阻力，防止落地后滑行
            Rb.drag = 2f;
            Rb.angularDrag = 2f;

            // 6. 启动落地检测协程
            landCheckCoroutine = StartCoroutine(CheckLanding());

            // 7. 启动生命周期计时（超时自动消失）
            lifetimeCoroutine = StartCoroutine(AutoDespawnAfterDelay());
        }

        // ======================================================================
        //  落地检测
        // ======================================================================

        private IEnumerator CheckLanding()
        {
            // 给一个最小飞行时间，避免刚发射就被判定落地
            float minFlightTime = 0.4f;
            float timer = 0f;

            while (!hasLanded)
            {
                timer += UnityEngine.Time.deltaTime;

                // 条件 A：至少飞了 minFlightTime
                // 条件 B：速度很低
                // 条件 C：在地面附近（Raycast 检测）
                if (timer > minFlightTime && Rb.velocity.magnitude < landVelocityThreshold)
                {
                    // 向下发射射线检测地面
                    if (Physics.Raycast(transform.position, Vector3.down, out RaycastHit hit,
                            groundCheckDistance, groundLayer))
                    {
                        // 停在落地点正上方
                        transform.position = new Vector3(
                            transform.position.x,
                            hit.point.y + groundYOffset,
                            transform.position.z
                        );

                        OnLand();
                        yield break;
                    }
                    else
                    {
                        // 速度很低但不在"地面"上 — 可能卡在半空
                        // 再等一小段时间强制落地
                        yield return new WaitForSeconds(0.5f);

                        if (!hasLanded)
                        {
                            // 强制落地：使用当前位置的 Y 作为地面
                            OnLand();
                            yield break;
                        }
                    }
                }

                yield return null; // 每帧检测
            }
        }

        private void OnLand()
        {
            hasLanded = true;
            Debug.Log($"[DropItemRune] 符文落地: {runeData?.runeName ?? "未知符文"}");

            // 冻结物理，符文稳稳停住
            if (Rb != null)
            {
                Rb.velocity = Vector3.zero;
                Rb.angularVelocity = Vector3.zero;
                Rb.isKinematic = true;
                Rb.useGravity = false;
            }

            // 将 transform 摆正（防止歪着插地上）
            transform.rotation = Quaternion.identity;

            // 关闭拖尾特效
            if (trail != null)
                trail.SetActive(false);
            if (realyFx != null)
                realyFx.SetActive(true);
        }

        // ======================================================================
        //  物理碰撞落地（比协程的速度检测更可靠）
        // ======================================================================

        private void OnCollisionEnter(Collision collision)
        {
            if (hasLanded) return;

            // 最小飞行时间保护，防止刚生成就误触落地
            if (UnityEngine.Time.time - launchTime < 0.5f) return;

            // 检查碰撞的物体是否属于 groundLayer
            int layerMask = 1 << collision.gameObject.layer;
            if ((groundLayer.value & layerMask) != 0)
            {
                OnLand();
            }
        }

        // ======================================================================
        //  超时自动消失
        // ======================================================================

        private IEnumerator AutoDespawnAfterDelay()
        {
            yield return new WaitForSeconds(maxLifetime);

            // 如果还没被捡走，超时自动销毁
            if (!DropItemData.isFlyingToPlayer && hasLanded)
            {
                Debug.Log($"[DropItemRune] 符文超时消失: {runeData?.runeName ?? "未知"}");
                DespawnSelf();
            }
        }

        // ======================================================================
        //  拾取到达（override 基类）
        // ======================================================================

        /// <summary>
        /// 符文飞到玩家身边后调用 — 存入局外背包并销毁
        /// </summary>
        protected override void OnReachPlayer()
        {
            if (runeData != null)
            {
                Debug.Log($"[DropItemRune] 玩家拾取符文: {runeData.runeName} (ID={runeData.runeId})");

                // 存入局外背包（不应用局内效果）
                RuneInventory.AddRune(runeData.runeId);
            }

            DespawnSelf();
        }

        // ======================================================================
        //  回收（本地直接销毁）
        // ======================================================================

        private void DespawnSelf()
        {
            Destroy(gameObject);
        }

        // ======================================================================
        //  OnDestroy 清理协程（防止销毁后协程还在跑）
        // ======================================================================

        private void OnDestroy()
        {
            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }
        }
    }
}

using System.Reflection;
using Controllers.Character;
using UnityEngine;
using XLua;

namespace Controllers.Rune
{
    /// <summary>
    /// 符文效果应用器。读取 RuneEquipmentSnapshot 中缓存的装备符文 ID，
    /// 优先从 Lua 热更新配置加载数值和效果映射，Lua 不可用时回退到 C# 硬编码。
    /// </summary>
    public static class RuneEffectApplier
    {
        // Lua 热更新模块缓存（避免每帧重复加载）
        private static LuaTable _luaMain;
        private static bool _luaLoaded;

        /// <summary>将已装备符文的效果应用到玩家属性上</summary>
        public static void ApplyEquippedRunes(AttributePlayerBase attributes)
        {
            var database = Resources.Load<RuneDatabaseSO>("RuneData/RuneDatabase");
            if (database == null || database.allRunes == null || database.allRunes.Count == 0)
            {
                Debug.LogWarning("[RuneEffectApplier] 未找到 RuneDatabase 或数据为空");
                return;
            }

            int[] equippedIds = RuneEquipmentSnapshot.GetAllEquippedIds();
            if (equippedIds.Length == 0)
            {
                Debug.Log("[RuneEffectApplier] 未装备任何符文");
                return;
            }

            // 加载 Lua 热更新配置（仅首次成功后缓存）
            LoadLuaConfig();

            string currentCharacterType = DetectCurrentCharacterType();

            foreach (int runeId in equippedIds)
            {
                // ── 尝试从 Lua 热更新配置获取覆盖值 ──
                LuaTable luaRuneConfig = GetLuaRuneConfig(runeId);

                if (luaRuneConfig != null)
                {
                    Debug.Log($"[RuneEffectApplier] 应用符文效果(Lua热更新): ID={runeId}");
                    ApplyFromLuaConfig(attributes, luaRuneConfig, currentCharacterType);
                }
                else
                {
                    // 回退到 ScriptableObject 默认值
                    var runeData = database.GetRuneById(runeId);
                    if (runeData == null)
                    {
                        Debug.LogWarning($"[RuneEffectApplier] 未在数据库中找到符文 ID: {runeId}");
                        continue;
                    }

                    Debug.Log($"[RuneEffectApplier] 应用符文效果(默认): {runeData.runeName} (ID={runeId})");
                    ApplyFromSO(attributes, runeData, currentCharacterType);
                }
            }

            LogFinalAttributes(attributes);
        }

        // ────────────────────────────────────
        //  Lua 配置加载
        // ────────────────────────────────────

        private static void LoadLuaConfig()
        {
            if (_luaLoaded) return;

            try
            {
                var luaEnv = LuaEnvManager.Instance.LuaEnv;
                if (luaEnv == null)
                {
                    Debug.LogWarning("[RuneEffectApplier] LuaEnv 未初始化，使用 C# 默认配置");
                    return;
                }

                var result = luaEnv.DoString("return require('Main')");
                if (result != null && result.Length > 0)
                {
                    _luaMain = result[0] as LuaTable;
                    _luaLoaded = true;
                    Debug.Log("[RuneEffectApplier] Lua 符文配置加载成功");
                }
            }
            catch (System.Exception e)
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 加载失败，使用 C# 默认配置: {e.Message}");
            }
        }

        private static LuaTable GetLuaRuneConfig(int runeId)
        {
            if (_luaMain == null) return null;
            var runeConfig = _luaMain.Get<LuaTable>("RuneConfig");
            return runeConfig?.Get<int, LuaTable>(runeId);
        }

        // ────────────────────────────────────
        //  Lua 路径：从 Lua 配置应用效果
        // ────────────────────────────────────

        private static void ApplyFromLuaConfig(AttributePlayerBase attr, LuaTable luaConfig, string currentCharType)
        {
            // 1. 应用基础 powers（数值 + 效果映射均来自 Lua）
            var powersTable = luaConfig.Get<LuaTable>("powers");
            int powerLen = powersTable != null ? powersTable.Length : 0;
            for (int i = 0; i < powerLen; i++)
            {
                var power = powersTable.Get<int, LuaTable>(i + 1); // Lua 索引从 1 开始
                if (power == null) continue;

                string label = power.Get<string>("label");
                int value = power.Get<int>("value");

                ApplyPowerFromLua(attr, label, value);
            }

            // 2. 应用特殊技能
            string specialName = luaConfig.Get<string>("specialPowerName");
            if (!string.IsNullOrEmpty(specialName))
            {
                ApplySpecialPowerFromLua(attr, luaConfig, specialName, currentCharType);
            }
        }

        private static void ApplyPowerFromLua(AttributePlayerBase attr, string label, int value)
        {
            if (_luaMain == null)
            {
                // 回退到 C# switch-case
                ApplyPower(attr, new RunePower { label = label, value = value });
                return;
            }

            var effectMap = _luaMain.Get<LuaTable>("RuneEffect");
            string methodName = effectMap?.Get<string>(label);

            if (string.IsNullOrEmpty(methodName))
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 未识别的符文效果标签: '{label}'，回退到 C#");
                ApplyPower(attr, new RunePower { label = label, value = value });
                return;
            }

            // 反射调用 AttributePlayerBase 的方法
            var method = typeof(AttributePlayerBase).GetMethod(
                methodName, BindingFlags.Public | BindingFlags.Instance);
            if (method != null)
            {
                method.Invoke(attr, new object[] { value });
                Debug.Log($"[RuneEffectApplier] Lua映射: {label} → {methodName}({value})");
            }
            else
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 映射的方法不存在: {methodName}");
            }
        }

        private static void ApplySpecialPowerFromLua(AttributePlayerBase attr, LuaTable luaConfig,
            string specialName, string currentCharType)
        {
            // 角色匹配检查
            string exclusiveType = luaConfig.Get<string>("exclusiveCharacterType");
            if (!string.IsNullOrEmpty(exclusiveType) && exclusiveType != currentCharType)
            {
                Debug.Log($"[RuneEffectApplier] 跳过专属符文效果 [{specialName}]：角色不匹配");
                return;
            }

            if (_luaMain == null) return;

            var specialPowers = _luaMain.Get<LuaTable>("RuneSpecialPower");
            LuaFunction luaFunc = specialPowers?.Get<LuaFunction>(specialName);

            if (luaFunc != null)
            {
                luaFunc.Call(attr);
                luaFunc.Dispose();
                Debug.Log($"[RuneEffectApplier] Lua特殊技能: {specialName} 已应用");
            }
            else
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 未定义的特殊技能: '{specialName}'");
            }
        }

        // ────────────────────────────────────
        //  C# 回退路径：原有逻辑保持不变
        // ────────────────────────────────────

        private static void ApplyFromSO(AttributePlayerBase attr, RuneDataSO runeData, string currentCharType)
        {
            foreach (var power in runeData.powers)
            {
                ApplyPower(attr, power);
            }

            if (!string.IsNullOrEmpty(runeData.specialPowerDescription))
                ApplySpecialPower(attr, runeData, currentCharType);
        }

        private static void ApplyPower(AttributePlayerBase attr, RunePower power)
        {
            switch (power.label)
            {
                case "%基础伤害":
                    attr.AddAttackPower(power.value);
                    Debug.Log($"[RuneEffectApplier] 攻击力 +{power.value}% → {attr.GetAttackPower()}");
                    break;

                case "%暴击率":
                    attr.AddCriticalChance(power.value);
                    Debug.Log($"[RuneEffectApplier] 暴击率 +{power.value}% → {attr.GetCriticalChance() * 100:F1}%");
                    break;

                case "%防御力":
                    attr.AddDefensePower(power.value);
                    Debug.Log($"[RuneEffectApplier] 防御力 +{power.value}% → {attr.GetDefensePower()}");
                    break;

                case "%攻击速度":
                    attr.ReduceAttackInterval(power.value);
                    Debug.Log($"[RuneEffectApplier] 攻击速度 +{power.value} → {attr.GetAttackSpeed()}");
                    break;

                default:
                    Debug.LogWarning($"[RuneEffectApplier] 未识别的符文效果标签: '{power.label}'");
                    break;
            }
        }

        private static void ApplySpecialPower(AttributePlayerBase attr, RuneDataSO runeData, string currentCharacterType)
        {
            if (!string.IsNullOrEmpty(runeData.exclusiveCharacterType))
            {
                if (runeData.exclusiveCharacterType != currentCharacterType)
                {
                    Debug.Log($"[RuneEffectApplier] 跳过专属符文效果 [{runeData.specialPowerName}]："
                              + $"角色 {currentCharacterType} 与符文专属角色 {runeData.exclusiveCharacterType} 不匹配");
                    return;
                }
                Debug.Log($"[RuneEffectApplier] 专属符文效果匹配！角色 {currentCharacterType} ✅");
            }

            Debug.Log($"[RuneEffectApplier] 应用特殊技能: {runeData.specialPowerName} → {runeData.specialPowerDescription}");

            switch (runeData.specialPowerName)
            {
                case "小法师专属：":
                    attr.AddMaxAttackCount(1);
                    attr.AddComboCount(1);
                    Debug.Log($"[RuneEffectApplier] 初始发射数量 +1 → {attr.GetMaxAttackCount()}");
                    break;

                default:
                    Debug.LogWarning($"[RuneEffectApplier] 未处理的特殊技能: '{runeData.specialPowerDescription}'");
                    break;
            }
        }

        // ────────────────────────────────────
        //  工具方法
        // ────────────────────────────────────

        private static string DetectCurrentCharacterType()
        {
            var player = Object.FindObjectOfType<PlayerController>();
            if (player == null)
            {
                Debug.LogWarning("[RuneEffectApplier] 未找到场景中的 PlayerController，无法检测角色类型");
                return string.Empty;
            }

            string typeName = player.GetType().Name;
            Debug.Log($"[RuneEffectApplier] 检测到当前角色类型: {typeName}");
            return typeName;
        }

        private static void LogFinalAttributes(AttributePlayerBase attr)
        {
            Debug.Log($"[RuneEffectApplier] ── 符文应用后最终属性 ──\n" +
                      $"攻击力: {attr.GetAttackPower()}\n" +
                      $"防御力: {attr.GetDefensePower()}\n" +
                      $"暴击率: {attr.GetCriticalChance() * 100:F1}%\n" +
                      $"攻击间隔: {attr.GetAttackInterval()}\n" +
                      $"移动速度: {attr.GetMoveSpeed()}");
        }
    }
}

// Assets/Scripts/Domain/Rune/RuneDataSO.cs
using System.Collections.Generic;
using UnityEngine;

[CreateAssetMenu(menuName = "Rune/Rune Data")]
public class RuneDataSO : ScriptableObject
{
    public int runeId;
    public string runeName;
    public Sprite icon;            // 默认图标（包体内保底）
    [Tooltip("图标文件名，热更新时从 AssetBundle 加载（如 icon_rune_1001）")]
    public string iconName;        // 热更新图标标识
    public Rarity rarity;          // Common / Epic / Legendary / 专属（未来掉落用）
    public List<RunePower> powers; // 属性修正列表
    public string specialPowerName;
    [TextArea] public string specialPowerDescription;
    [Tooltip("专属符文绑定的角色类型（如 WizardBoy / BingNv），配合 ApplySpecialPower 判断")]
    public string exclusiveCharacterType; // 为空表示全局通用
}

[System.Serializable]
public struct RunePower
{
    public int value;      // e.g. 30
    public string label;   // e.g. "%基础伤害"
}

public enum Rarity { Common, Epic, Legendary, Exclusive }

using System.Collections.Generic;
using Core;
using Controllers.Rune;
using UI.Framework;
using UI.Framework.Base;
using UI.Framework.Manager;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using UI.Framework.Animation;

public class ShopPanel : UIScreen
{
  [Header("商店符文列表（与符文面板一致）")]
  [SerializeField] private GameObject runeSlotPrefab;
  [SerializeField] private Transform runeSlotContainer;

  [Header("详情信息（只显示名字、描述、价格）")]
  [SerializeField] private GameObject detailPanel;
  [SerializeField] private TextMeshProUGUI detailName;
  [SerializeField] private TextMeshProUGUI detailDescription;
  [SerializeField] private TextMeshProUGUI detailPrice;
  [SerializeField] private Button purchaseButton;

  [Header("金币显示")]
  [SerializeField] private TextMeshProUGUI coinText;

  [SerializeField] private ShopRuneDatabaseSO shopDatabase;

  private List<GameObject> shopRuneSlots = new List<GameObject>();
  private ShopRuneConfigSO selectedRune;
  private RuneSlot selectedRuneSlot;
  private bool isListenerInitialized;

  protected override void Awake()
  {
    screenId = "ShopPanel";
    base.Awake();
    UIManager.Instance.RegisterScreen(this);
  }

  protected override void Start()
  {
    base.Start();
    ResolveDetailReferences();
    InitializeShop();
  }

  protected override void OnBeforeOpen()
  {
    base.OnBeforeOpen();
    EnsureListenerInitialized();
    UpdateCoinDisplay();
    RefreshShopItems();
  }

  protected override void OnAfterClose()
  {
    base.OnAfterClose();
    ClearSelection();
  }

  private void ResolveDetailReferences()
  {
    if (detailName == null)
      detailName = FindChildTMP("DetailName");
    if (detailDescription == null)
      detailDescription = FindChildTMP("DetailDescription");
    if (detailPrice == null)
      detailPrice = FindChildTMP("DetailPrice");
    if (purchaseButton == null)
      purchaseButton = GetComponentInChildren<Button>(true);
  }

  private TextMeshProUGUI FindChildTMP(string name)
  {
    var child = transform.Find(name);
    return child != null ? child.GetComponent<TextMeshProUGUI>() : null;
  }

  private void EnsureListenerInitialized()
  {
    if (isListenerInitialized) return;
    isListenerInitialized = true;

    if (purchaseButton != null)
    {
      purchaseButton.onClick.AddListener(OnPurchaseClicked);
      if (purchaseButton.GetComponent<ButtonFloatAnim>() == null)
        purchaseButton.gameObject.AddComponent<ButtonFloatAnim>();
    }

    var coinChannel = EventChannelLocator.MainContainer?.coinUpdateChannel;
    if (coinChannel != null)
    {
      coinChannel.OnEventRaised += OnCoinUpdated;
    }
  }

  private void InitializeShop()
  {
    EnsureListenerInitialized();

    if (detailPanel != null)
    {
      detailPanel.SetActive(false);
    }
  }

  private void OnCoinUpdated(CoinUpdateData data)
  {
    UpdateCoinDisplay();
  }

  private void RefreshShopItems()
  {
    // 刷新列表时旧 slot 会被销毁，清空选中引用
    selectedRuneSlot = null;

    foreach (var slot in shopRuneSlots)
    {
      Destroy(slot);
    }
    shopRuneSlots.Clear();

    if (shopDatabase == null)
    {
      Debug.LogError("[ShopPanel] shopDatabase 未赋值");
      return;
    }

    if (runeSlotPrefab == null || runeSlotContainer == null)
    {
      Debug.LogError("[ShopPanel] runeSlotPrefab 或 runeSlotContainer 未赋值");
      return;
    }

    foreach (var runeConfig in shopDatabase.shopRunes)
    {
      GameObject slotObj = Instantiate(runeSlotPrefab, runeSlotContainer);
      ShopRuneSlot shopSlot = slotObj.AddComponent<ShopRuneSlot>();

      RuneSlot runeSlot = slotObj.GetComponent<RuneSlot>();
      if (runeSlot != null)
      {
        shopSlot.Initialize(runeSlot, runeConfig, OnRuneSelected);
      }

      shopRuneSlots.Add(slotObj);
    }
  }

  private void UpdateCoinDisplay()
  {
    if (coinText != null)
    {
      int coins = Managers.CoinManager.Instance.GetCoins();
      coinText.text = $"金币: {coins}";
    }
  }

  private void OnRuneSelected(ShopRuneConfigSO runeConfig, RuneSlot runeSlot)
  {
    // 取消上一个选中项的背景图
    if (selectedRuneSlot != null && selectedRuneSlot != runeSlot)
    {
      selectedRuneSlot.PlayDeselect();
    }

    // 选中当前项，切换背景图
    selectedRuneSlot = runeSlot;
    if (runeSlot != null && !runeSlot.IsSelected)
    {
      runeSlot.PlaySelect();
    }

    selectedRune = runeConfig;

    // 显示详情面板
    if (detailPanel != null)
    {
      detailPanel.SetActive(true);
    }

    // 更新详情文本（不依赖 detailPanel 是否赋值）
    if (detailName != null)
      detailName.text = runeConfig.runeName;
    if (detailDescription != null)
      detailDescription.text = runeConfig.description;
    if (detailPrice != null)
      detailPrice.text = $"{runeConfig.price} ";

    UpdatePurchaseButtonState();

    // 使用RuneInfoChannel展示详情信息，与RunePanel保持一致
    if (runeConfig.runeData != null)
    {
      var runePowers = new Dictionary<int, string>();
      if (runeConfig.runeData.powers != null)
      {
        foreach (var power in runeConfig.runeData.powers)
        {
          runePowers[power.value] = power.label;
        }
      }

      var args = new Core.RuneEquipArgs(
          runeConfig.runeId,
          runeConfig.runeData.runeName,
          runePowers,
          runeConfig.runeData.specialPowerName,
          runeConfig.runeData.specialPowerDescription
      );
      EventChannelLocator.MainContainer.runeInfoChannel.Raise(args);
    }
  }

  private void OnPurchaseClicked()
  {
    if (selectedRune == null)
    {
      Debug.LogWarning("[ShopPanel] 购买失败：未选中符文");
      return;
    }

    Debug.Log($"[ShopPanel] 点击购买，runeId={selectedRune.runeId}, price={selectedRune.price}, allowRepeat={selectedRune.allowRepeatPurchase}");
    bool success = Managers.ShopManager.Instance.PurchaseRune(selectedRune.runeId);
    Debug.Log($"[ShopPanel] 购买结果: {success}");

    if (success)
    {
      RefreshShopItems();
      UpdatePurchaseButtonState();
    }
  }

  private void UpdatePurchaseButtonState()
  {
    if (purchaseButton == null || selectedRune == null) return;

    bool isAvailable = Managers.ShopManager.Instance.IsRuneAvailable(selectedRune.runeId);
    bool hasPurchased = !selectedRune.allowRepeatPurchase && RuneInventory.HasRune(selectedRune.runeId);
    int currentCoins = Managers.CoinManager.Instance.GetCoins();
    bool canAfford = currentCoins >= selectedRune.price;

    purchaseButton.interactable = isAvailable && !hasPurchased && canAfford;

    var btnText = purchaseButton.GetComponentInChildren<TextMeshProUGUI>();
    if (btnText != null)
    {
      btnText.text = hasPurchased ? "已购买" : (purchaseButton.interactable ? "购买" : "不可购买");
    }
  }

  private void ClearSelection()
  {
    if (selectedRuneSlot != null && selectedRuneSlot.IsSelected)
    {
      selectedRuneSlot.PlayDeselect();
    }
    selectedRuneSlot = null;
    selectedRune = null;

    if (detailPanel != null)
    {
      detailPanel.SetActive(false);
    }
  }

  void OnDestroy()
  {
    var coinChannel = EventChannelLocator.MainContainer?.coinUpdateChannel;
    if (coinChannel != null)
    {
      coinChannel.OnEventRaised -= OnCoinUpdated;
    }
  }
}

